package com.bank.setops;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class SetOpsDao {
    private static final Logger log = Logger.getLogger(SetOpsDao.class.getName());
    private final Connection conn;

    public SetOpsDao(Connection conn) { this.conn = conn; }

    private List<String> run(String label, String sql) throws Exception {
        List<String> out = new ArrayList<>();
        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
            while (rs.next()) out.add(rs.getString(1));
        }
        log.info(() -> label + " -> " + out);
        return out;
    }

    public List<String> union() throws Exception {
        return run("UNION (distinct, either product)",
            "SELECT customer FROM savings_holders UNION SELECT customer FROM creditcard_holders");
    }

    public List<String> unionAll() throws Exception {
        return run("UNION ALL (keeps duplicates, fastest)",
            "SELECT customer FROM savings_holders UNION ALL SELECT customer FROM creditcard_holders");
    }

    public List<String> intersect() throws Exception {
        return run("INTERSECT (both products)",
            "SELECT customer FROM savings_holders INTERSECT SELECT customer FROM creditcard_holders");
    }
}
