package com.bank.setops;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.logging.Logger;

public class SetOpsDemo {
    private static final Logger log = Logger.getLogger(SetOpsDemo.class.getName());

    public static void main(String[] args) throws Exception {
        try (Connection conn = DriverManager.getConnection(
                "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret")) {
            SetOpsDao dao = new SetOpsDao(conn);
            dao.union();       // 4 distinct names
            dao.unionAll();    // 6 names (duplicates kept)
            dao.intersect();   // 2 names in both lists
            log.info("UNION=dedup; UNION ALL=keep dups+fast; INTERSECT=common rows.");
        }
    }
}
